<div class="space-y-6"><x-ui.breadcrumbs :items="[['label' => 'Report cards']]" /><x-ui.page-header title="Report cards" description="Published report-card snapshots from your school." />@forelse($cards as $card)<x-ui.snapshot-card :title="$card->exam?->name" status="published" :meta="'GPA '.$card->gpa.' · '.ucfirst($card->overall_status)"><x-ui.alert type="success">This report card is a published historical snapshot.</x-ui.alert></x-ui.snapshot-card>@empty<x-ui.empty-state title="No published report cards" message="Your published report cards will appear here." />@endforelse</div>
